<script setup lang="ts">
import {ref,computed,onMounted,onBeforeUnmount,watch,nextTick} from 'vue';
import FocusShare from './FocusShare.vue';
import FocusForest from './FocusForest.vue';
import FocusSettings from './FocusSettings.vue';import FocusReports from './FocusReports.vue';import {focusApi,duration,localDate} from './api';import {noise,stopNoise,alarm,unlockAudio} from './audio';import {connectFocus} from './realtime';import './focus.css';
defineProps<{csrf?:string|null}>();
const data=ref<any>(null),section=ref('Today'),search=ref(''),title=ref(''),loading=ref(true),busy=ref(false),toast=ref(''),error=ref(''),editor=ref<any>(null),dialog=ref<HTMLDialogElement|null>(null),kind=ref('task'),projectId=ref<number|null>(null),taskPage=ref(1),selectedTask=ref(''),timerMode=ref('countdown'),now=ref(Date.now()),offset=ref(0),bell=ref(false),live=ref('connecting'),lastSync=ref(''),social=ref<any>({groups:[],rankings:[]}),socialCompany=ref(''),socialPeriod=ref('month'),socialSearch=ref(''),groupMode=ref('mine'),groupDetails=ref<any>(null),timerBox=ref<HTMLElement|null>(null);
const showCompleted=ref(false),quickEstimate=ref(1),quickDue=ref('');
const displayName=window.portal?.admin?'Super Admin':window.portal?.employee?.name||'My workspace';
const shareData=ref<{title:string;lines:string[]}|null>(null),sort=ref('default');
function shareTask(task:any){shareData.value={title:task.title,lines:[task.completed_at?'Status: Completed':'Status: To do','Project: '+(projects.value.find((p:any)=>p.id===task.project_id)?.name||'Inbox'),'Due: '+(task.due_date||'Not scheduled'),'Priority: '+task.priority,'Estimated focus: '+task.estimate+' sessions',...task.subtasks.map((t:any)=>(t.done?'[x] ':'[ ] ')+t.title)]};}
function shareList(){const list=filtered.value;shareData.value={title:projectId.value?'Project: '+section.value:section.value+' | Task list',lines:[list.length+' tasks | '+duration(estimates.value)+' estimated focus',...list.slice(0,50).map((t:any)=>(t.completed_at?'[x] ':'[ ] ')+t.title+(t.due_date?' | '+t.due_date:'')),...(list.length>50?['Plus '+(list.length-50)+' more tasks.']:[])]};}
const refreshing=ref(false);let refreshRevision=0,loadPromise:Promise<void>|null=null;let reloadPending=false;let interval:number|undefined,toastTimer:number|undefined,disconnect:(()=>void)|undefined,deadline:number|null=null,disposed=false;
function message(text:string){toast.value=text;clearTimeout(toastTimer);toastTimer=window.setTimeout(()=>toast.value='',4500);}
async function run(fn:()=>Promise<void>,success=''){if(busy.value)return;busy.value=true;refreshRevision++;error.value='';try{await fn();if(success)message(success);}catch(e:any){error.value=e.message;}finally{busy.value=false;}}
async function load():Promise<void>{
 reloadPending=true;if(loadPromise)return loadPromise;
 refreshing.value=true;
 loadPromise=(async()=>{do{reloadPending=false;const revision=refreshRevision;try{
 const next=await focusApi('data');if(disposed)return;if(revision!==refreshRevision){reloadPending=true;continue;}
const oldIds=new Set(data.value?.notifications.map((n:any)=>n.id)||[]);if(data.value&&'Notification'in window&&Notification.permission==='granted'){for(const n of next.notifications.filter((n:any)=>!n.read_at&&!oldIds.has(n.id)))new Notification('Focus To Do',{body:n.title});}data.value=next;offset.value=Date.parse(next.server_now)-Date.now();lastSync.value=new Date().toLocaleTimeString();if(!socialCompany.value&&next.companies.length)socialCompany.value=String(next.companies[0].id);if(!next.timer&&!next.tasks.some((t:any)=>String(t.id)===selectedTask.value&&!t.completed_at))selectedTask.value=String(next.tasks.find((t:any)=>!t.completed_at)?.id||'');error.value='';
 }catch(e:any){if(!disposed)error.value=e.message;}finally{loading.value=false;}
 }while(reloadPending&&!disposed);})();
 try{await loadPromise;}finally{loadPromise=null;refreshing.value=false;}
}

const active=computed(()=>data.value?.timer),elapsed=computed(()=>active.value?Number(active.value.elapsed_seconds)+(active.value.status==='running'?Math.min(Math.max(0,Math.floor((now.value+offset.value-Date.parse(active.value.segment_started_at))/1000)),active.value.target_seconds-active.value.elapsed_seconds):0):0);
const clock=computed(()=>{const value=active.value?active.value.mode==='stopwatch'?elapsed.value:Math.max(0,active.value.target_seconds-elapsed.value):(data.value?.settings.focus_minutes||25)*60;return `${String(Math.floor(value/60)).padStart(2,'0')}:${String(Math.floor(value%60)).padStart(2,'0')}`;});
const progress=computed(()=>active.value?Math.min(100,elapsed.value/active.value.target_seconds*100):0),projects=computed(()=>data.value?.projects.filter((p:any)=>!p.is_folder)||[]),folders=computed(()=>data.value?.projects.filter((p:any)=>p.is_folder)||[]);
const navigation=computed(()=>['Today','Tasks',...(data.value?.settings.lists||[]),'Timer','Reports',...(data.value?.settings.groups?['Groups']:[]),...(data.value?.settings.forest?['Forest']:[]),...(data.value?.settings.ranking?['Ranking']:[]),'Settings']);
const utility=['Timer','Reports','Groups','Forest','Ranking','Settings'];
const isTaskView=computed(()=>!!projectId.value||!utility.includes(section.value));
const primaryLists=computed(()=>['Today','Tomorrow','This week','Planned','Events','Completed','Tasks'].filter(n=>navigation.value.includes(n)));
const extraLists=computed(()=>navigation.value.filter(n=>!utility.includes(n)&&!primaryLists.value.includes(n)));
function shortTime(seconds:number){const minutes=Math.floor(seconds/60);return minutes>=60?Math.floor(minutes/60)+'h '+minutes%60+'m':minutes+'m';}

function select(name:string,id:number|null=null){section.value=name;projectId.value=id;showCompleted.value=false;taskPage.value=1;search.value='';if(['Groups','Ranking'].includes(name))void loadSocial();}
function matchesList(t:any,name:string){const today=data.value?.today||localDate(),date=t.due_date;if(name==='Completed')return !!t.completed_at;if(t.completed_at)return false;
 switch(name){case 'Today':return date===today;case 'Tasks':return !t.project_id;case 'Tomorrow':{const d=new Date(today+'T12:00:00');d.setDate(d.getDate()+1);return date===localDate(d);}case 'This week':{const d=new Date(today+'T12:00:00');d.setDate(d.getDate()+7-((d.getDay()+6)%7)-1);return date&&date>=today&&date<=localDate(d);}case 'Next 7 days':{const d=new Date(today+'T12:00:00');d.setDate(d.getDate()+6);return date&&date>=today&&date<=localDate(d);}case 'Planned':return !!date;case 'Someday':return !date;case 'Overdue':return date&&date<today;case 'Events':return !!t.remind_at;case 'High priority':return t.priority==='high';case 'Medium priority':return t.priority==='medium';case 'Low priority':return t.priority==='low';default:return true;}}
const filtered=computed(()=>data.value?.tasks.filter((t:any)=>(projectId.value?t.project_id===projectId.value&&(!t.completed_at||showCompleted.value):matchesList(showCompleted.value?{...t,completed_at:null}:t,section.value))&&[t.title,t.notes,...t.tags].join(' ').toLowerCase().includes(search.value.toLowerCase()))||[]),pages=computed(()=>Math.max(1,Math.ceil(filtered.value.length/10))),visible=computed(()=>{const rows=[...filtered.value];if(sort.value==='priority')rows.sort((a:any,b:any)=>['high','medium','low','none'].indexOf(a.priority)-['high','medium','low','none'].indexOf(b.priority));if(sort.value==='due')rows.sort((a:any,b:any)=>(a.due_date||'9999').localeCompare(b.due_date||'9999'));if(sort.value==='name')rows.sort((a:any,b:any)=>a.title.localeCompare(b.title));return rows.slice((taskPage.value-1)*10,taskPage.value*10);});
watch([search,sort],()=>taskPage.value=1);watch(pages,n=>taskPage.value=Math.min(taskPage.value,n));
function estimateList(name:string,id?:number){const tasks=data.value?.tasks.filter((t:any)=>id?t.project_id===id&&!t.completed_at:matchesList(t,name)&&!t.completed_at)||[];return shortTime(tasks.reduce((n:number,t:any)=>n+t.estimate*(data.value?.settings.focus_minutes||25)*60,0));}
function count(name:string,id?:number){return data.value?.tasks.filter((t:any)=>id?t.project_id===id&&!t.completed_at:matchesList(t,name)).length||0;}
const estimates=computed(()=>filtered.value.filter((t:any)=>!t.completed_at).reduce((sum:number,t:any)=>sum+t.estimate*data.value.settings.focus_minutes*60,0));
function newTaskDate(){if(projectId.value)return null;if(section.value==='Tomorrow'){const d=new Date(data.value.today+'T12:00:00');d.setDate(d.getDate()+1);return localDate(d);}return ['Today','This week','Next 7 days','Planned'].includes(section.value)?data.value.today:null;}
const blankTask=()=>({title:'',notes:'',project_id:projectId.value,priority:section.value==='High priority'?'high':section.value==='Medium priority'?'medium':section.value==='Low priority'?'low':'none',estimate:1,due_date:newTaskDate(),remind_at:null,repeat:'none',tags:[],subtasks:[]});
async function open(type:string,item?:any){kind.value=type;groupDetails.value=null;
 editor.value=type==='task'?(item?JSON.parse(JSON.stringify(item)):blankTask()):type==='project'||type==='folder'?{name:'',color:'#7762ee',folder_id:null,is_folder:type==='folder',...(item||{})}:type==='manual'?{task_id:selectedTask.value,started_at:'',minutes:25,...(item?{id:item.id,task_id:item.task_id,started_at:localInput(item.started_at),minutes:Math.round(item.elapsed_seconds/60)}:{})}:type==='group'?{name:'',description:''}:{confirmation:''};
 if(type==='task'){editor.value.tagText=editor.value.tags.join(', ');editor.value.remindLocal=editor.value.remind_at?localInput(editor.value.remind_at):'';}
 await nextTick();dialog.value?.showModal();}
function localInput(value:string){const d=new Date(value);return `${localDate(d)}T${String(d.getHours()).padStart(2,'0')}:${String(d.getMinutes()).padStart(2,'0')}`;}
function close(){dialog.value?.close();editor.value=null;}
async function save(){await run(async()=>{const e=editor.value;if(kind.value==='task')await focusApi('tasks'+(e.id?'/'+e.id:''),'POST',{...e,tags:e.tagText.split(',').map((s:string)=>s.trim()).filter(Boolean),remind_at:e.remindLocal?new Date(e.remindLocal).toISOString():null});
 else if(['project','folder'].includes(kind.value))await focusApi('projects'+(e.id?'/'+e.id:''),'POST',e);
 else if(kind.value==='manual')await focusApi('manual'+(e.id?'/'+e.id:''),'POST',{...e,started_at:new Date(e.started_at).toISOString()});
 else if(kind.value==='group'){await focusApi('groups','POST',{...e,company_id:Number(socialCompany.value),action:'create'});await loadSocial();}
 else if(kind.value==='clear'){await focusApi('clear','POST',e);select('Today');}
 close();await load();},'Saved successfully.');}
async function addTask(){if(!title.value.trim())return;await run(async()=>{await focusApi('tasks','POST',{...blankTask(),title:title.value.trim(),estimate:quickEstimate.value,...(quickDue.value?{due_date:quickDue.value}:{})});title.value='';quickEstimate.value=1;quickDue.value='';await load();},'Task added.');}
async function complete(task:any,event:Event){
 const checkbox=event.target as HTMLInputElement,desired=checkbox.checked;
 if(busy.value||refreshing.value){checkbox.checked=!!task.completed_at;return;}
 await run(async()=>{
  await focusApi(`tasks/${task.id}/complete`,'POST',{completed:desired});
  refreshRevision++;
  const current=data.value?.tasks.find((t:any)=>t.id===task.id);if(current)current.completed_at=desired?new Date().toISOString():null;
  if(desired&&data.value.settings.completion_sound)alarm(20,'chime');await load();
 },desired?'Task completed. You can find it in Completed.':'Task reopened.');
 if(checkbox.isConnected)checkbox.checked=!!data.value?.tasks.find((t:any)=>t.id===task.id)?.completed_at;
}

async function removeTask(){if(!confirm('Delete this task? Its recorded focus time is retained.'))return;await run(async()=>{await focusApi('tasks/'+editor.value.id,'DELETE');close();await load();},'Task deleted.');}
async function removeProject(){if(!confirm('Delete this project/folder? Tasks move to Tasks; focus records stay available.'))return;await run(async()=>{await focusApi('projects/'+editor.value.id,'DELETE');close();select('Tasks');await load();},'Project deleted.');}
async function timer(action:string){if(['start','resume'].includes(action))unlockAudio();await run(async()=>{const result=await focusApi('timer','POST',{action,task_id:Number(selectedTask.value),session_id:active.value?.id,mode:timerMode.value});data.value.timer=result.timer;offset.value=Date.parse(result.server_now)-Date.now();if(action==='start'||action==='resume')noise(data.value.settings.noise,data.value.settings.noise_volume);else stopNoise();await load();});}
function focusTask(task:any){selectedTask.value=String(task.id);select('Timer');}
async function loadSocial(){if(!socialCompany.value)return;try{social.value=await focusApi(`social?company_id=${socialCompany.value}&period=${socialPeriod.value}`);}catch(e:any){error.value=e.message;}}
watch([socialCompany,socialPeriod],loadSocial);
async function group(action:string,g:any){await run(async()=>{await focusApi('groups','POST',{action,id:g.id,company_id:Number(socialCompany.value)});await loadSocial();},'Group updated.');}
const groups=computed(()=>social.value.groups.filter((g:any)=>(groupMode.value==='discover'||g.mine)&&[g.name,g.description].join(' ').toLowerCase().includes(socialSearch.value.toLowerCase()))),pending=computed(()=>data.value?.pending_sunlight??(data.value?.rewards.filter((r:any)=>!r.collected_at&&r.grams>0).reduce((n:number,r:any)=>n+r.grams,0)||0)),level=computed(()=>Math.floor((data.value?.sunlight||0)/600));
async function readNotifications(task?:any){await run(async()=>{await focusApi('notifications','POST',task?{id:task.id}:{});await load();if(task?.task_id){const found=data.value.tasks.find((t:any)=>t.id===task.task_id);if(found)await open('task',found);}});}
async function fullscreen(){try{if(document.fullscreenElement)await document.exitFullscreen();else await timerBox.value?.requestFullscreen();}catch{message('Fullscreen is unavailable in this browser.');}}
async function enableNotifications(){if('Notification'in window){const result=await Notification.requestPermission();message(result==='granted'?'Browser notifications enabled while this workspace is open.':'Browser notifications were not enabled.');}}
function outside(event:PointerEvent){document.querySelectorAll<HTMLDetailsElement>('.ft-row-menu[open],.ft-list-menu[open],.ft-quick-date[open]').forEach(menu=>{if(!menu.contains(event.target as Node))menu.open=false;});if(!(event.target as HTMLElement)?.closest('.ft-bell'))bell.value=false;}
function escape(event:KeyboardEvent){if(event.key==='Escape')bell.value=false;}
function visibility(){if(document.visibilityState==='visible')void load();}
onMounted(async()=>{await load();disconnect=connectFocus(()=>document.querySelector<HTMLMetaElement>('meta[name="csrf-token"]')?.content||'',()=>{if(!busy.value){void load();if(['Groups','Ranking'].includes(section.value))void loadSocial();}},state=>live.value=state,()=>{void load();});interval=window.setInterval(async()=>{now.value=Date.now();if(active.value?.status==='running'&&elapsed.value>=active.value.target_seconds&&deadline!==active.value.id){deadline=active.value.id;stopNoise();alarm(data.value.settings.alarm_volume,active.value.phase==='focus'?data.value.settings.alarm:(data.value.settings.break_alarm||'chime'));await timer('sync');deadline=null;}},1000);document.addEventListener('visibilitychange',visibility);document.addEventListener('pointerdown',outside);document.addEventListener('keydown',escape);});
onBeforeUnmount(()=>{disposed=true;clearInterval(interval);clearTimeout(toastTimer);disconnect?.();stopNoise();document.removeEventListener('visibilitychange',visibility);document.removeEventListener('pointerdown',outside);document.removeEventListener('keydown',escape);});
</script>
<template><main class="ft-workspace" :class="'ft-bg-'+(data?.settings.background||'plain')"><header class="ft-page-header"><div class="ft-user"><span class="ft-user-avatar" aria-hidden="true">{{displayName.slice(0,1)}}</span><strong>{{displayName}}</strong><h1 class="ft-visually-hidden">Focus To Do</h1></div><nav class="ft-header-tools" aria-label="Focus tools"><button v-for="tool in ['Groups','Forest','Ranking','Reports'].filter(n=>navigation.includes(n))" :key="tool" :aria-label="tool" :title="tool" :class="{active:section===tool}" @click="select(tool)"><svg width="21" height="21" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" aria-hidden="true"><path v-if="tool==='Groups'" d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2m20 0v-2a4 4 0 0 0-3-4M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8Zm8-7a4 4 0 0 1 0 7"/><path v-else-if="tool==='Reports'" d="M3 20V10h4v10m4 0V4h4v16m4 0V8h3v12M2 21h21"/><path v-else-if="tool==='Forest'" d="M12 22V9m0 6C3 15 2 8 3 5c6 0 9 3 9 10Zm0-4c0-7 3-9 9-9 0 7-3 9-9 9Z"/><path v-else-if="tool==='Ranking'" d="M8 3h8v8a4 4 0 0 1-8 0V3Zm0 2H3v3a5 5 0 0 0 5 5m8-8h5v3a5 5 0 0 1-5 5M12 15v6m-5 0h10"/><path v-else-if="tool==='Settings'" d="M9 3h6l1 3 3 1 2 5-2 5-3 1-1 3H9l-1-3-3-1-2-5 2-5 3-1 1-3Zm3 5a4 4 0 1 0 0 8 4 4 0 0 0 0-8Z"/><path v-else d="M9 2h6m-3 5v6l3 2M21 13a9 9 0 1 1-18 0 9 9 0 0 1 18 0Z"/></svg></button><div class="ft-bell"><button aria-label="Notifications" title="Notifications" @click="bell=!bell"><svg width="21" height="21" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" aria-hidden="true"><path d="M18 8a6 6 0 0 0-12 0c0 8-3 8-3 10h18c0-2-3-2-3-10M10 21h4"/></svg><span v-if="data?.notifications.filter((n:any)=>!n.read_at).length" class="ft-badge">{{data.notifications.filter((n:any)=>!n.read_at).length}}</span></button><section v-if="bell" class="ft-notifications"><div class="ft-heading"><strong>Notifications</strong><button aria-label="Close notifications" @click="bell=false">&times;</button></div><button @click="readNotifications()">Mark all read</button><button @click="enableNotifications">Enable browser alerts</button><div class="ft-notification-list"><button v-for="n in data?.notifications" :class="{unread:!n.read_at}" @click="readNotifications(n)"><strong>{{n.title}}</strong><small>{{new Date(n.created_at).toLocaleString()}}</small></button><p v-if="!data?.notifications.length" class="ft-empty">No notifications.</p></div></section></div><button aria-label="Settings" title="Settings" :class="{active:section==='Settings'}" @click="select('Settings')"><svg width="21" height="21" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" aria-hidden="true"><path d="M9 3h6l1 3 3 1 2 5-2 5-3 1-1 3H9l-1-3-3-1-2-5 2-5 3-1 1-3Zm3 5a4 4 0 1 0 0 8 4 4 0 0 0 0-8Z"/></svg></button></nav></header>
<div v-if="toast" class="ft-toast" role="status">✓ {{toast}}</div><div v-if="error" class="ft-error" role="alert">{{error}}<button aria-label="Dismiss error" @click="error=''">×</button></div><p v-if="loading" class="ft-empty">Loading your workspace…</p>
<div v-else-if="data" class="ft-layout"><aside class="ft-sidebar"><div class="ft-sidebar-search"><svg width="17" height="17" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" aria-hidden="true"><circle cx="10" cy="10" r="7"/><path d="m15 15 6 6"/></svg><input v-model="search" type="search" placeholder="Search" aria-label="Search tasks"></div><button v-for="name in primaryLists" :class="{active:section===name&&!projectId}" @click="select(name)"><span><svg class="ft-nav-glyph" aria-hidden="true" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5"><path v-if="['Timer','Today','Tomorrow'].includes(name)" d="M12 8v5l3 2M20 12a8 8 0 1 1-16 0 8 8 0 0 1 16 0Z"/><path v-else-if="name==='Reports'" d="M4 20V10h4v10m4 0V4h4v16m4 0V8M2 21h20"/><path v-else d="M5 4h14v16H5zM8 8h8M8 12h8M8 16h5"/></svg>{{name==='This week'?'This Week':name}}</span><small v-if="!utility.includes(name)">{{count(name)}}<span class="ft-nav-time">{{estimateList(name)}}</span></small></button><details v-if="extraLists.length" class="ft-extra-lists"><summary>More lists</summary><button v-for="name in extraLists" :key="name" :class="{active:section===name}" @click="select(name)">{{name}}<small>{{count(name)}}</small></button></details><div class="ft-heading ft-sidebar-heading"><p class="ft-eyebrow">PROJECTS</p><button aria-label="Create project" @click="open('project')">+</button></div><button v-for="p in projects.filter((p:any)=>!p.folder_id)" :class="{active:projectId===p.id}" @click="select(p.name,p.id)"><span><i :style="{background:p.color}"></i>{{p.name}}</span><small>{{count('',p.id)}}<span class="ft-nav-time">{{estimateList('',p.id)}}</span></small></button><details v-for="f in folders" class="ft-folder"><summary>{{f.name}}<button aria-label="Edit folder" @click.prevent="open('folder',f)">⋯</button></summary><button v-for="p in projects.filter((p:any)=>p.folder_id===f.id)" :class="{active:projectId===p.id}" @click="select(p.name,p.id)"><span><i :style="{background:p.color}"></i>{{p.name}}</span><small>{{count('',p.id)}}<span class="ft-nav-time">{{estimateList('',p.id)}}</span></small></button></details><footer class="ft-sidebar-footer"><button @click="open('project')">+ Add Project</button><button aria-label="Create folder" title="New folder" @click="open('folder')"><svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" aria-hidden="true"><path d="M3 5h7l2 3h9v12H3V5Zm9 6v6m-3-3h6"/></svg></button></footer><a href="/products">← All products</a></aside>
<section class="ft-content" :class="{'ft-list-content':isTaskView}"><header class="ft-section-header"><h2>{{section}}</h2><details class="ft-list-menu" v-if="isTaskView"><summary aria-label="List options" title="List options"><svg width="19" height="19" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><path d="M7 3v18m-4-4 4 4 4-4M17 21V3m-4 4 4-4 4 4"/></svg></summary><div><label>Sort tasks<select v-model="sort" aria-label="Sort tasks"><option value="default">Custom order</option><option value="due">Due date</option><option value="priority">Priority</option><option value="name">Task name</option></select></label><button @click="shareList">Share {{projectId?'project':'list'}}</button><button v-if="projectId" @click="open('project',projects.find((p:any)=>p.id===projectId))">Edit project</button><button :disabled="busy" @click="load">Sync now</button><small :title="lastSync">Sync: {{live}}</small></div></details></header>
<template v-if="isTaskView"><div class="ft-stats"><article><small>Estimated Time</small><strong>{{shortTime(estimates)}}</strong></article><article><small>Tasks to be Completed</small><strong>{{filtered.filter((t:any)=>!t.completed_at).length}}</strong></article><article><small>Elapsed Time Today</small><strong>{{shortTime(data.summary.seconds)}}</strong></article><article><small>Completed Tasks Today</small><strong>{{data.summary.completed}}</strong></article></div><article class="ft-panel ft-task-panel"><form v-if="section!=='Completed'" class="ft-add" @submit.prevent="addTask"><span aria-hidden="true">+</span><input v-model="title"  :placeholder="'Add a task to '+(projectId?section:'Tasks')+', press Enter to save'" aria-label="New task" maxlength="250" required><div class="ft-quick-estimates" aria-label="Estimated focus sessions"><button v-for="n in 5" :key="n" type="button" :class="{selected:quickEstimate>=n}" :aria-label="n+' focus sessions'" :aria-pressed="quickEstimate===n" @click="quickEstimate=n"><svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" aria-hidden="true"><path d="M9 2h6m-3 5v5l2 2M20 13a8 8 0 1 1-16 0 8 8 0 0 1 16 0Z"/></svg></button></div><details class="ft-quick-date"><summary aria-label="Set task date" title="Set task date"><svg width="19" height="19" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" aria-hidden="true"><path d="M3 5h18v16H3zM7 2v6m10-6v6M3 10h18"/></svg></summary><label>Due date<input v-model="quickDue" type="date"></label></details><button class="ft-visually-hidden" type="submit" :disabled="busy">Add task</button></form><div v-for="task in visible" :key="task.id" class="ft-task-row" :class="{'ft-task-completed':!!task.completed_at}"><input type="checkbox" :checked="!!task.completed_at" :disabled="busy||refreshing" :aria-label="task.completed_at?'Reopen task':'Complete task'" @change="complete(task,$event)"><button class="ft-task-title" :class="{done:task.completed_at}" @click="open('task',task)"><strong>{{task.title}}</strong><small><span v-if="task.project_id">{{projects.find((p:any)=>p.id===task.project_id)?.name}} · </span>{{task.due_date||'No due date'}}<span v-if="task.repeat!=='none'"> · Repeats {{task.repeat}}</span><span v-if="task.tags.length"> · {{task.tags.map((t:string)=>'#'+t).join(' ')}}</span></small></button><span v-if="task.completed_at" class="ft-task-status">Completed</span><span v-else class="ft-priority" :class="task.priority">{{task.priority==='none'?'':task.priority}}</span><small class="ft-estimate">{{task.estimate}} sessions</small><button v-if="!task.completed_at" title="Focus on this task" @click="focusTask(task)">▷ Focus</button><details class="ft-row-menu"><summary :aria-label="'Task actions: '+task.title">&middot;&middot;&middot;</summary><div><button @click="open('task',task)">Edit task</button><button title="Share task" :aria-label="'Share task: '+task.title" @click="shareTask(task)">Share task</button></div></details></div><div v-if="!filtered.length" class="ft-empty"><div class="ft-empty-icon"><svg width="28" height="28" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" aria-hidden="true"><path d="m12 3 2 6 7 3-7 2-2 7-2-7-7-2 7-3 2-6Zm7-2v5m-2-2h5"/></svg></div><h3>No tasks yet</h3><p>Add something you'd love to move forward today.</p><button v-if="section!=='Completed'" @click="open('task')">+ Add your first task</button></div><button v-if="section!=='Completed'" class="ft-show-completed" @click="showCompleted=!showCompleted">{{showCompleted?'Hide completed tasks':'Show completed tasks'}}</button><footer v-if="filtered.length" class="ft-pagination"><small>{{filtered.length}} tasks · Page {{taskPage}} of {{pages}}</small><div><button :disabled="taskPage===1" @click="taskPage--">Previous</button><button :disabled="taskPage===pages" @click="taskPage++">Next</button></div></footer></article></template>
<template v-else-if="section==='Timer'"><div ref="timerBox" class="ft-focus-stage" :class="{'ft-timer-running':active?.status==='running'}"><div class="ft-heading"><span class="ft-pill">{{active?active.phase==='focus'?'Focus time':active.phase==='long'?'Long break':'Short break':'Ready to focus'}}</span><button @click="fullscreen">Full screen</button></div><select v-model="selectedTask" :disabled="!!active"><option value="">Select a task</option><option v-for="t in data.tasks.filter((t:any)=>!t.completed_at)" :value="String(t.id)">{{t.title}}</option></select><h3 v-if="active">{{active.task_title||'Focus session'}}</h3><div class="ft-clock" :style="{'--progress':progress+'%'}"><span>{{clock}}</span><small>{{active?.status||'One task. Your full attention.'}}</small></div><div class="ft-timer-actions"><template v-if="!active"><select v-model="timerMode"><option value="countdown">Pomodoro</option><option value="stopwatch">Stopwatch</option></select><button class="ft-primary" :disabled="busy||!selectedTask" @click="timer('start')">Start focus</button></template><template v-else><button class="ft-primary" :disabled="busy" @click="timer(active.status==='running'?'pause':'resume')">{{active.status==='running'?'Pause':'Start / resume'}}</button><button :disabled="busy" @click="timer('stop')">{{active.phase==='focus'?'Finish session':'Skip break'}}</button><button :disabled="busy" @click="timer('reset')">Reset</button></template></div><p class="ft-muted">{{data.settings.focus_minutes}} min focus · {{data.settings.short_break}} min short break · {{data.settings.long_break}} min long break</p><button @click="noise(data.settings.noise,data.settings.noise_volume)">Play selected ambience</button><button @click="stopNoise">Mute</button></div><article class="ft-panel"><h3>Today’s rhythm</h3><p class="ft-muted">{{duration(data.summary.seconds)}} focused · {{data.summary.completed}} tasks completed</p><div v-for="s in data.sessions.filter((s:any)=>localDate(new Date(s.started_at))===data.today).slice(0,12)" class="ft-report-row"><span>{{s.task_title||'Session'}} <small class="ft-muted">· {{s.phase}} · {{s.status}}</small></span><strong>{{duration(s.elapsed_seconds)}}</strong></div></article></template>
<FocusReports v-else-if="section==='Reports'" :data="data" @manual="record=>open('manual',record)"/>
<template v-else-if="section==='Groups'||section==='Ranking'"><div class="ft-toolbar"><label>Company<select v-model="socialCompany"><option v-for="c in data.companies" :value="String(c.id)">{{c.name}}</option></select></label><label>Period<select v-model="socialPeriod"><option value="month">Last 30 days</option><option value="overall">Overall</option></select></label><button @click="loadSocial">Refresh</button><button v-if="section==='Groups'&&socialCompany" class="ft-primary" @click="open('group')">+ Create group</button></div><p class="ft-muted">Only active Focus users in this company are included. Personal tasks and notes remain private. Manual records do not affect rankings.</p><p v-if="!socialCompany" class="ft-empty">Ask your administrator to assign a company to use groups and rankings.</p><template v-else-if="section==='Groups'"><div class="ft-toolbar"><div class="ft-tabs"><button :class="{active:groupMode==='mine'}" @click="groupMode='mine'">My groups</button><button :class="{active:groupMode==='discover'}" @click="groupMode='discover'">Discover</button></div><input v-model="socialSearch" placeholder="Find a group…"></div><div class="ft-card-grid"><article v-for="g in groups" class="ft-panel"><span class="ft-empty-icon">◎</span><h3>{{g.name}}</h3><p class="ft-muted">{{g.description}}</p><p>{{g.members.length}} members · {{duration(g.seconds)}}</p><div class="ft-actions"><button @click="groupDetails=groupDetails?.id===g.id?null:g">Members</button><button :disabled="busy" @click="group(g.mine?'leave':'join',g)">{{g.mine?'Leave':'Join group'}}</button><button v-if="g.owned" :disabled="busy" @click="group('delete',g)">Delete</button></div><div v-if="groupDetails?.id===g.id" class="ft-members"><p v-for="m in g.members">{{m.name}} <strong>{{duration(m.seconds)}}</strong></p></div></article></div><p v-if="!groups.length" class="ft-empty">No groups here yet. Create one or explore Discover.</p></template><article v-else class="ft-panel ft-table-scroll"><table><thead><tr><th>Position</th><th>Member</th><th>Focus time</th></tr></thead><tbody><tr v-for="(person,index) in social.rankings" :class="{ 'ft-you':person.you}"><td>{{Number(index)+1}}</td><td>{{person.name}} {{person.you?'(You)':''}}</td><td>{{duration(person.seconds)}}</td></tr></tbody></table></article></template>
<template v-else-if="section==='Forest'"><FocusForest :sunlight="data.sunlight" :pending="pending" :busy="busy" @collect="run(async()=>{await focusApi('collect','POST',{});await load();},'Sunlight collected.')"/><article class="ft-panel"><h3>Sunlight activity</h3><div v-for="r in data.rewards.filter((r:any)=>r.grams>0).slice(0,30)" class="ft-report-row"><div>{{r.reason}}<small class="ft-muted">{{new Date(r.created_at).toLocaleString()}}</small></div><strong>+{{r.grams}}g {{r.collected_at?'collected':'available'}}</strong></div></article></template>
<FocusSettings v-else-if="section==='Settings'" :settings="data.settings" :busy="busy" @save="s=>run(async()=>{await focusApi('settings','POST',s);await load();},'Preferences saved.')" @clear="open('clear')"/>
</section></div>
<div v-if="data&&section!=='Timer'" class="ft-timer-dock"><button class="ft-dock-time" title="Open timer" aria-label="Open timer" @click="select('Timer')">{{active?clock:data.settings.focus_minutes}}</button><span class="ft-dock-wave" aria-hidden="true"></span><button :disabled="busy||(!active&&!selectedTask)" :aria-label="active?(active.status==='running'?'Pause focus':'Resume focus'):'Start focus'" @click="timer(active?(active.status==='running'?'pause':'resume'):'start')"><svg width="23" height="23" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" aria-hidden="true"><circle cx="12" cy="12" r="10"/><path v-if="active?.status==='running'" d="M9 8v8m6-8v8"/><path v-else d="m10 7 7 5-7 5V7Z"/></svg></button></div>
<dialog ref="dialog" class="ft-dialog" :class="{'ft-task-drawer':kind==='task'}" @cancel="close" @click="e=>{if(e.target===dialog)close();}"><template v-if="editor"><header class="ft-heading"><div><p class="ft-eyebrow">FOCUS TO DO</p><h2>{{kind==='task'?(editor.id?'Task details':'New task'):kind==='manual'?'Manual focus record':kind==='clear'?'Delete Focus data':kind==='group'?'Create a group':editor.id?'Edit '+kind:'New '+kind}}</h2></div><button type="button" aria-label="Close dialog" @click="close">×</button></header><form @submit.prevent="save"><div class="ft-dialog-body"><template v-if="kind==='task'"><label>Task name<input v-model="editor.title" maxlength="250" required autofocus></label><div class="ft-fields"><label>Project<select v-model="editor.project_id"><option :value="null">Tasks / inbox</option><option v-for="p in projects" :value="p.id">{{p.name}}</option></select></label><label>Priority<select v-model="editor.priority"><option v-for="p in ['none','low','medium','high']">{{p}}</option></select></label><label>Estimated focus sessions<input v-model.number="editor.estimate" type="number" min="0" max="999" required></label><label>Due date<input v-model="editor.due_date" type="date"></label><label>Reminder<input v-model="editor.remindLocal" type="datetime-local"></label><label>Repeat<select v-model="editor.repeat"><option v-for="p in ['none','daily','weekly','monthly','yearly']">{{p}}</option></select></label></div><label>Tags (comma separated)<input v-model="editor.tagText" placeholder="work, planning"></label><label>Notes<textarea v-model="editor.notes" rows="4" maxlength="15000"></textarea></label><div class="ft-heading"><h3>Subtasks</h3><button type="button" @click="editor.subtasks.push({title:'',done:false})">+ Add subtask</button></div><div v-for="(sub,index) in editor.subtasks" class="ft-subtask"><input v-model="sub.done" type="checkbox" aria-label="Subtask complete"><input v-model="sub.title" placeholder="Subtask" required maxlength="250"><button type="button" aria-label="Remove subtask" @click="editor.subtasks.splice(index,1)">×</button></div><p v-if="editor.completed_at" class="ft-muted">Completed {{new Date(editor.completed_at).toLocaleString()}}</p></template>
<template v-else-if="kind==='project'||kind==='folder'"><label>Name<input v-model="editor.name" maxlength="120" required></label><label>Colour<input v-model="editor.color" type="color"></label><label v-if="kind==='project'">Folder<select v-model="editor.folder_id"><option :value="null">No folder</option><option v-for="f in folders" :value="f.id">{{f.name}}</option></select></label></template>
<template v-else-if="kind==='manual'"><p class="ft-muted">Manual focus appears in your reports, but earns no sunlight or ranking credit.</p><label>Task<select v-model="editor.task_id" required><option v-for="t in data.tasks" :value="t.id">{{t.title}}</option></select></label><label>Started at<input v-model="editor.started_at" type="datetime-local" required></label><label>Minutes<input v-model.number="editor.minutes" type="number" min="1" max="1440" required></label><h3>Recent manual records</h3><button v-for="record in data.sessions.filter((s:any)=>s.manual).slice(0,10)" type="button" class="ft-manual-record" @click="open('manual',record)">{{record.task_title}} · {{duration(record.elapsed_seconds)}} · Edit</button></template>
<template v-else-if="kind==='group'"><label>Group name<input v-model="editor.name" maxlength="120" required></label><label>Description<textarea v-model="editor.description" maxlength="1000"></textarea></label></template>
<template v-else><p>This permanently deletes your Focus To Do data. Type <strong>DELETE MY FOCUS DATA</strong> to confirm.</p><input v-model="editor.confirmation" required pattern="DELETE MY FOCUS DATA" aria-label="Delete confirmation"></template><p v-if="error" class="ft-error" role="alert">{{error}}</p></div><footer class="ft-dialog-footer"><button v-if="editor.id&&kind==='task'" type="button" class="ft-danger" :disabled="busy" @click="removeTask">Delete task</button><button v-if="editor.id&&['project','folder'].includes(kind)" type="button" class="ft-danger" :disabled="busy" @click="removeProject">Delete {{kind}}</button><button type="button" @click="close">Cancel</button><button class="ft-primary" :disabled="busy">{{busy?'Saving…':kind==='clear'?'Delete my data':'Save changes'}}</button></footer></form></template></dialog>
<FocusShare v-if="shareData" :title="shareData.title" :lines="shareData.lines" @close="shareData=null"/></main></template>
